  // G3 restore gate (gh-178): a persisted triple that no longer forms a
  // valid binding is never applied mixed. Auto-repair keeps the
  // boot-coherent model with a loud diagnostic naming the conflicted
  // fields and the repair (OQ3: repair, not halt — the session still
  // boots, on a coherent quadruple).
  final gate = restoreGateDecision(
    providerResolvable: true,
    bindingResolves: _restoreBindingResolves(providerKind, modelId, baseUrl),
    persistedModelId: modelId,
    providerName: providerKind,
    repairModelId: _agent.state.model.id,
  );
  if (gate.verdict != RestoreGateVerdict.restore) {
    io.writeln(_style.dim('note: ${gate.refusal!.message}'));
    io.writeln(
      _style.dim(
        '      keeping ${_agent.state.model.id} '
        '(${_agent.state.model.provider} @ ${_agent.state.model.baseUrl})',
      ),
    );
    return;
  }
  final spec = resolveCliProviderSpec(built.provider)!;
  // The resolved KIND feeds the session state and the stream factory —
  // a raw name-shaped id here would throw at providerStreamFunction
  // (the crash this PR removes at boot) and persist itself back into
  // the state file via onProviderChanged (issue #772 review).
  _activeCustomName = entry?.name;
  _providerKind = spec.kind;
  final key = _providerKeyFor(spec, built.baseUrl) ?? '';
  _apiKey = key;
  _explicitToken = false;
  if (_restoreUsesRolesChain(entry, key)) {
    final applied = _repinRolesChain(
      resolver: config.modelRolesResolver!,
      spec: spec,
      built: built,
      entry: entry,
      key: key,
      previous: previous,
    );
    if (!applied) return;
  } else {
    _streamFunction = _catalogStreamFunction(spec.kind, key);
    _agent.streamFunction = _streamFunction;
  }
  if (key.isEmpty) {
    io.writeln(_style.dim(_restoreKeyHint(entry, built.baseUrl)));
  } else {
    _noteKeyShadowing(entry, built.baseUrl);
  }
  await _finishRestoreBinding(session, built: built, entry: entry);
}

/// Whether the CLI is already on the binding the restore would apply —
/// the boot applied this folder's state, and a re-apply must not
/// restart the model cache or append a duplicate `model_change`.
bool _restoreBindingSatisfied(
  String modelId,
  String? baseUrl,

  String? baseUrl,
  String? customProviderName,
) {
  final current = _agent.state.model;
  return current.id == modelId &&
      current.baseUrl == baseUrl &&
      (customProviderName == null || _activeCustomName == customProviderName);
}

/// Whether the restore re-points the stream through the roles resolver:
/// roles-driven boots with a resolver. A genuinely keyless endpoint (no
/// entry key slot and nothing resolved) is excluded — roles chains
/// cannot form there by design, so the restore keeps the legacy direct
/// wiring, exactly as before gh-1000.
bool _restoreUsesRolesChain(CustomProviderEntry? entry, String key) {
  if (!_rolesDriven) return false;
  if (config.modelRolesResolver == null) return false;
  return !(key.isEmpty && entry?.keyName == null);
}

/// The saved entry a pinned NAME resolves to. A name that no longer
/// resolves must not unpin silently (E1, leaf-pin variant) — say so,
/// exactly like the folder-state branch, before the endpoint-keyed
/// fallback can bind a twin account's key.
CustomProviderEntry? _pinnedRestoreEntry(String? customProviderName) {
  if (customProviderName == null) return null;
  final entry = config.customProviders?.find(customProviderName);
  if (entry != null) return entry;
  io.writeln(
    _style.dim(
      'note: saved provider "$customProviderName" is no longer '
      'configured — resolved by endpoint (model kept)',
    ),
  );
  return null;
}

/// G3 (gh-178): whether the persisted `(kind, modelId, baseUrl)` triple
/// still resolves through the ONE validating constructor. A null
/// persisted endpoint resolves the record default first — the same
/// resolution `buildCliDefaultModel` applies — so legacy states without
/// a recorded baseUrl are judged on the triple they would actually bind.
/// Unknown/private endpoints pass leniently (nothing to judge them by);
/// canonical-endpoint dialect/family conflicts refuse.
bool _restoreBindingResolves(
  String providerKind,
  String modelId,
  String? baseUrl,
) {
  final effective =
      baseUrl?.trim() ??
      resolveCliProviderSpec(providerKind)?.defaultBaseUrl ??
      '';
  if (effective.isEmpty) return true;
  try {
    ProviderModelBinding.resolve(
      providerKind: providerKind,
      modelId: modelId,
      baseUrl: effective,
      provenance: BindingProvenance.restore,
    );
    return true;
  } on ConfigException {
    return false;
  }
}

/// Builds the restored model with the issue-#964 authHeader precedence:
/// the PINNED entry's own header wins — two entries can share one
/// endpoint (the gh-1000 twin fixture), and the endpoint-first scan
/// would otherwise bind the twin's (missing) header. Returns null (the
/// stale note is printed) when the saved kind no longer resolves.
Model? _buildRestoredModel({
  required String providerKind,
  required String modelId,
  required String? baseUrl,
  required CustomProviderEntry? entry,
}) {
  try {
    return buildCliDefaultModel(
      providerKind,
      modelId: modelId,
      baseUrl: baseUrl,
      authHeader:
          entry?.authHeader ??
          authHeaderForBaseUrl(
            config.customProviders?.entries ?? const [],
            baseUrl,
          ),
    );
  } on ConfigException {
    io.writeln(
      _style.dim(
        'note: saved model state is stale ($providerKind) — '
        'keeping ${_agent.state.model.id}',
      ),
    );
    return null;
  }
}

/// Captures the CLI wiring fields the restore is about to mutate, so a
/// FAILED roles re-pin can roll every one of them back (T3).
_RestoreWiring _captureRestoreWiring() => (
  customName: _activeCustomName,
  providerKind: _providerKind,
  apiKey: [REDACTED:Sensitive Value],
  explicitToken: _explicitToken,
  streamFunction: _streamFunction,
);

/// Rolls every captured wiring field back onto the CLI (and the agent's
/// live stream) — the model that serves keeps describing itself
/// consistently in the status bar and the transcript.
void _rollbackRestoreWiring(_RestoreWiring previous) {
  _activeCustomName = previous.customName;
  _providerKind = previous.providerKind;
  _apiKey = previous.apiKey;
  _explicitToken = previous.explicitToken;
  _streamFunction = previous.streamFunction;
  _agent.streamFunction = previous.streamFunction;
}

/// Roles mode: re-pin the default chain onto the restored provider —
/// the same wiring a live `/provider` switch builds. The resolved key
/// material is seeded under the pinned key name FIRST: a store-backed

Future<void> _handleModelCommand(String rest) async {
  final trimmed = rest.trim();
  if (trimmed == '?') {
    await _listModels('');
    return;
  }
  if (trimmed.isEmpty) {
    // Bare `/model` in TUI mode opens the interactive picker; in line mode
    // it prints the active model and the roles overview.
    final controller = _tuiController;
    if (controller != null) {
      controller.openModelMenu();
      return;
    }
    await _switchModel('');
    return;
  }
  if (await _switchModelByNumber(trimmed)) return;
  // A custom model definition from the models: config section resolves
  // before plain model ids (its provider/endpoint/token limits come from
  // the definition, not the current connection).
  final custom = config.modelsConfig?.custom[trimmed];
  if (custom != null) {
    await _switchToCustomModel(trimmed, custom);
    return;
  }
  // G1 switch gate (gh-178): resolve a `provider/model` form BEFORE the
  // plain switch. A cross-provider prefix moves the WHOLE triple through
  // the provider-switch flow; the same-provider reuse path below is for
  // current-triple model ids only.
  switch (parseTypedModelTarget(
    trimmed,
    activeProvider: _agent.state.model.provider,
    activeCustomName: _activeCustomName,
    activeModelIds: _modelCandidates('').toSet(),
    isKnownProvider: _isKnownModelProvider,
  )) {
    case SameModelSwitch(:final modelId):
      await _switchModel(modelId);
    case CrossProviderSwitch(:final provider, :final modelId):
      await _switchCrossProviderModel('$provider|$modelId');
    case RefusedSwitch(:final refusal):
      io.writeln(refusal.message);
  }
}

/// The `/model N` branch of [_handleModelCommand]: resolves a 1-based
/// number against the last listed models. Returns true when [trimmed] was
/// a number (handled — valid pick or invalid-selection message).
Future<bool> _switchModelByNumber(String trimmed) async {
  final number = int.tryParse(trimmed);
  if (number == null) return false;
  await _switchModelOrReport(
    number,
    _lastModelList ?? _numberedListFallback(),
  );
  return true;
}

/// The numbered-list fallback when no `/models` listing ran yet: the
/// ACTIVE identity's own ids, each tagged with that identity (gh-178 G1

      role,
      cwd: resolver.cwd,
      homeDir: resolver.homeDir,
    );
    if (chain == null) return 'inherits main';
    return chain.map((ref) => ref.modelId).join(' → ');
  }

  io.writeln(
    _style.dim(
      '  note: role models unchanged — smol (compaction): '
      '${label(smolModelRole)} · subagent: ${label("subagent")} · '
      'memory: ${label("memory")} — /settings → Agent models to adjust',
    ),
  );
}

Future<void> _switchModel(String modelId) async {
  final current = _agent.state.model;
  final rolesResolver = config.modelRolesResolver;
  if (modelId.isEmpty) {
    io.writeln('model: ${current.id} (${current.api})');
    if (rolesResolver != null) io.writeln(rolesResolver.describeRoles());
    return;
  }
  // G1 backstop (gh-178): EVERY construction site below reuses the
  // CURRENT triple (`provider: current.provider` / `baseUrl:
  // current.baseUrl` / `authHeader: current.authHeader`) — that shape is
  // valid ONLY for a same-provider pick. A cross-provider reference that
  // reaches here (a flow the routing above should have caught) is
  // refused loudly instead of silently producing the incident's mixed
  // triple; the repair routes through the whole-triple flow.
  switch (parseTypedModelTarget(
    modelId,
    activeProvider: current.provider,
    activeCustomName: _activeCustomName,
    activeModelIds: _modelCandidates('').toSet(),
    // The backstop refuses only on CACHE EVIDENCE: with no model list
    // for the active endpoint there is nothing to distinguish a
    // cross-provider reference from a vendor-prefixed id that endpoint
    // serves (OpenRouter's `openai/gpt-4o`), and the coherent legacy
    // pasthrough wins. The routing paths above use the real resolver.
    isKnownProvider: _modelCandidates('').isNotEmpty
        ? _isKnownModelProvider
        : (_) => false,
  )) {
    case SameModelSwitch():
      break;
    case CrossProviderSwitch():
      io.writeln(
        const ModelCoherenceRefusal(
          problem:
              '"/model" reuse cannot carry a cross-provider pick — '
              'model ids never ride a foreign provider/endpoint/key '
              'triple',
          fields: ['provider', 'baseUrl', 'key'],
          repair:
              '/model <provider>/<id> resolves the whole triple, or '
              '/provider <provider> first',
        ).message,
      );
      return;
    case RefusedSwitch(:final refusal):
      io.writeln(refusal.message);
      return;
  }
  // An endpoint-reported window/cap beats the carried one (the catalog
  // defaults) when the id is known to /models.
  final window = _modelContextWindows[modelId] ?? current.contextWindow;
  final cap = _modelMaxTokens[modelId] ?? current.maxTokens;
  // Cookie-header auth (CodeMie SSO) can never ride a roles chain — the
  // chain stream would send the cookie as Bearer. Keep the direct model
  // set (the cookie stays in model.headers), mirroring
  // [_switchCodeMieProvider]'s resolver bypass.
  final cookieAuth = current.headers?.containsKey('cookie') ?? false;
  if (rolesResolver != null && !cookieAuth) {
    // Roles mode: pin the default role to the requested model id on the
    // current provider (a single-entry chain for this session). The
    // endpoint's scoped key name rides along (see _switchProvider).
    final pinnedKeyName =
        _rolesKeyNameFor(current.provider, current.baseUrl) ??
        _scopedKeyNameForNonDefault(current.provider, current.baseUrl);
    // Seed the resolver with the session's LIVE key material under the
    // pinned name BEFORE resolving the chain: saved-entry keys (CodeMie
    // JWT, typed custom keys) live in the secure store / session, never
    // in the resolver's startup snapshot — an unseeded pin resolves
    // nothing and chainFor throws "no usable chain entry: set
    // OPENAI_API_KEY", which aborts the switch and leaves the status
    // line on the old model.
    if (pinnedKeyName != null) {
      if (_apiKey.isNotEmpty) {
        rolesResolver.addSecret(pinnedKeyName, _apiKey);
      } else {
        _seedEnvKeyStack(rolesResolver, pinnedKeyName);
      }
    }
    rolesResolver.setDefaultChain([
      ModelRef(
        provider: current.provider,
        modelId: modelId,
        baseUrl: current.baseUrl,
        contextWindow: window,
        maxTokens: cap,
        apiKeyName: pinnedKeyName,
        // A saved entry's authHeader must survive /model switches
        // (issue #964) — the pin rebuilds the model.
        authHeader: current.authHeader,
      ),
    ]);
    rolesResolver.applyToAgent(_agent);
    _streamFunction = _agent.streamFunction;

